import{_ as d,o as e,a as o,b as c}from"./app.C41L12d5.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMT API","link":"/api/SIMT-API/SIMT-API"},{"text":"概述","link":"/api/SIMT-API/overview"}]},"headers":[],"relativePath":"api/SIMT-API/overview.md","filePath":"api/SIMT-API/overview.md","outlineHeaders":[{"level":2,"title":"接口分类","slug":"接口分类","link":"#接口分类"},{"level":2,"title":"调用接口依赖的头文件和库文件说明","slug":"调用接口依赖的头文件和库文件说明","link":"#调用接口依赖的头文件和库文件说明"}],"lastUpdated":1787050286000}'),a={name:"api/SIMT-API/overview.md"};function r(i,t,_,s,n,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<div><article class="markdown-body"><h1>概述</h1><h2 id="接口分类">接口分类<a class="header-anchor" href="#接口分类">​</a></h2><p>SIMT API是面向AI处理器的并行计算编程接口，可以实现高效的数据并行计算。SIMT API支持两种编程模型：SIMT编程、SIMD与SIMT混合编程，用户可先阅读<a href="SIMT_programming_intro/SIMT_programming_intro.html">SIMT编程简介</a>和<a href="SIMD_SIMT_hybrid_programming_intro/SIMD_SIMT_hybrid_programming_intro.html">SIMD与SIMT混合编程简介</a>，以了解编程基础，后续章节将详细介绍API接口。</p><p><strong>表1</strong> SIMT API分类列表</p><table><thead><tr><th>类别</th><th>功能</th></tr></thead><tbody><tr><td><a href="sync_and_memory_fence/sync_and_memory_fence.html">同步与内存栅栏</a></td><td>内存管理与同步接口，解决不同核内的线程间可能存在的数据竞争以及线程的同步问题。</td></tr><tr><td><a href="atomic_operations/atomic_operations.html">原子操作</a></td><td>对UB或Global Memory上的数据与指定数据执行原子操作的一系列接口。</td></tr><tr><td><a href="Warp_functions/Warp_functions.html">Warp函数</a></td><td>对单个Warp内32个线程的数据进行处理的相关操作的一系列API接口。</td></tr><tr><td><a href="math_functions/math_functions.html">数学函数</a></td><td>用于处理数学运算的函数集合以及不同精度、数据类型的转换函数集合</td></tr><tr><td><a href="address_space_predicate_functions/address_space_predicate_functions.html">地址空间谓词函数</a></td><td>判断输入指针是否为指定空间的地址。</td></tr><tr><td><a href="address_space_conversion_functions/address_space_conversion_functions.html">地址空间转换函数</a></td><td>将指定地址空间的地址值转换为指针，或将输入的指针转换为对应内存空间的地址值的接口。</td></tr><tr><td><a href="memory_access_functions/memory_access_functions.html">访存函数</a></td><td>数据加载和数据缓存相关接口。</td></tr><tr><td><a href="cooperative_groups/cooperative_groups.html">协作组</a></td><td>提供一套标准且安全的机制，实现更高效的线程并行协作。</td></tr><tr><td><a href="../Utils-API/tuning_interface/tuning_interface.html">调测接口</a></td><td>SIMT VF调试场景下使用的相关接口。</td></tr></tbody></table><h2 id="调用接口依赖的头文件和库文件说明">调用接口依赖的头文件和库文件说明<a class="header-anchor" href="#调用接口依赖的头文件和库文件说明">​</a></h2><p>安装CANN软件包并配置Ascend C编译环境后，编译SIMT源文件时才能引用SIMT API头文件。SIMT API公开头文件位于<code>${INSTALL_DIR}/asc/include/simt_api/</code>目录下，代码中通过<code>#include &quot;simt_api/xxx.h&quot;</code>方式引用。<code>${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径，以root用户安装为例，默认路径为<code>/usr/local/Ascend/cann</code>。</p><p><strong>表2</strong> 头文件列表</p><table><thead><tr><th>头文件</th><th>定位</th></tr></thead><tbody><tr><td><code>simt_api/asc_simt.h</code></td><td>SIMT基础API聚合头文件，适用于常规SIMT编程场景。</td></tr><tr><td><code>simt_api/common_functions.h</code></td><td>SIMT通用能力头文件，提供SIMT VF调用等基础定义。</td></tr><tr><td><code>simt_api/device_functions.h</code></td><td>设备函数头文件，覆盖地址空间谓词、地址空间转换、访存函数、Lane-ID类函数等接口，并包含同步、原子和Warp函数头文件。</td></tr><tr><td><code>simt_api/device_sync_functions.h</code></td><td>同步与内存栅栏接口头文件。</td></tr><tr><td><code>simt_api/device_atomic_functions.h</code></td><td>原子操作接口头文件。</td></tr><tr><td><code>simt_api/device_warp_functions.h</code></td><td>Warp级投票、数据交换和规约接口头文件。</td></tr><tr><td><code>simt_api/math_functions.h</code></td><td>数学函数和数值转换函数头文件，主要覆盖除<code>half</code>、<code>half2</code>、<code>bfloat16_t</code>、<code>bfloat16x2_t</code>、FP8相关类型外的数据类型接口。</td></tr><tr><td><code>simt_api/vector_functions.h</code></td><td>短向量构造函数头文件。</td></tr><tr><td><code>simt_api/cooperative_groups.h</code></td><td>协作组接口头文件。</td></tr><tr><td><code>simt_api/asc_fp16.h</code></td><td><code>half</code>、<code>half2</code>类型SIMT接口头文件。</td></tr><tr><td><code>simt_api/asc_bf16.h</code></td><td><code>bfloat16_t</code>、<code>bfloat16x2_t</code>类型SIMT接口头文件。</td></tr><tr><td><code>simt_api/asc_fp8.h</code></td><td><code>hifloat8x2_t</code>、<code>float8_e4m3x2_t</code>、<code>float8_e5m2x2_t</code>类型SIMT接口头文件。</td></tr></tbody></table><p>使用SIMT API时，请根据实际调用的接口包含对应头文件。</p><p><strong>表3</strong> 各类SIMT API需要包含的头文件</p><table><thead><tr><th>类别</th><th>需要包含的头文件</th></tr></thead><tbody><tr><td><a href="sync_and_memory_fence/sync_and_memory_fence.html">同步与内存栅栏</a></td><td><code>#include &quot;simt_api/device_sync_functions.h&quot;</code></td></tr><tr><td><a href="atomic_operations/atomic_operations.html">原子操作</a></td><td><code>#include &quot;simt_api/device_atomic_functions.h&quot;</code></td></tr><tr><td><a href="Warp_functions/Warp_functions.html">Warp函数</a></td><td><code>#include &quot;simt_api/device_warp_functions.h&quot;</code></td></tr><tr><td><a href="math_functions/math_functions.html">数学函数</a></td><td>数学函数标准库接口：<code>#include &quot;simt_api/math_functions.h&quot; </code><br><br>数学函数的intrinsic接口：<code>#include &quot;simt_api/device_functions.h&quot;</code></td></tr><tr><td><a href="address_space_predicate_functions/address_space_predicate_functions.html">地址空间谓词函数</a><br><br><a href="address_space_conversion_functions/address_space_conversion_functions.html">地址空间转换函数</a><br><br><a href="memory_access_functions/memory_access_functions.html">访存函数</a></td><td><code>#include &quot;simt_api/device_functions.h&quot;</code></td></tr><tr><td><a href="cooperative_groups/cooperative_groups.html">协作组</a></td><td><code>#include &quot;simt_api/cooperative_groups.h&quot;</code></td></tr></tbody></table><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>表3为按接口类别给出的最小依赖头文件；若已包含<code>simt_api/asc_simt.h</code>，则无需再单独包含<code>device_sync_functions.h</code>、<code>device_atomic_functions.h</code>、<code>device_warp_functions.h</code>、<code>math_functions.h</code>、<code>device_functions.h</code>和<code>vector_functions.h</code>。</p></div><p>使用<code>half</code>、<code>half2</code>、<code>bfloat16_t</code>、<code>bfloat16x2_t</code>、<code>hifloat8x2_t</code>、<code>float8_e4m3x2_t</code>、<code>float8_e5m2x2_t</code>等数据类型相关接口时，还需按表4包含对应扩展头文件。</p><p><strong>表4</strong> 不同数据类型下使用接口需要包含的头文件</p><table><thead><tr><th>数据类型</th><th>需要包含的头文件</th></tr></thead><tbody><tr><td>除<code>half</code>、<code>half2</code>、<code>bfloat16_t</code>、<code>bfloat16x2_t</code>、<code>hifloat8x2_t</code>、<code>float8_e4m3x2_t</code>、<code>float8_e5m2x2_t</code>以外的类型</td><td><code>#include &quot;simt_api/asc_simt.h&quot;</code></td></tr><tr><td><code>half</code>、<code>half2</code></td><td><code>#include &quot;simt_api/asc_fp16.h&quot;</code></td></tr><tr><td><code>bfloat16_t</code>、<code>bfloat16x2_t</code></td><td><code>#include &quot;simt_api/asc_bf16.h&quot;</code></td></tr><tr><td><code>hifloat8x2_t</code>、<code>float8_e4m3x2_t</code>、<code>float8_e5m2x2_t</code></td><td><code>#include &quot;simt_api/asc_fp8.h&quot;</code></td></tr></tbody></table><p>SIMT API属于核函数（Kernel）侧基础接口，使用时无需额外链接库文件。</p></article></div>',1)])])}const f=d(a,[["render",r]]);export{p as __pageData,f as default};
